def load_config(config_path):
    """Load config from local or GCS path."""
    path_str = str(config_path)
    if path_str.startswith("gs://"):
        with _open_file(path_str, "r") as f:
            return yaml.safe_load(f)
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)


def _json_safe(obj):
    """Convert config snapshots to JSON/msgpack-friendly Python values."""
    if obj is None or isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, Path):
        return str(obj)
    if isinstance(obj, np.generic):
        return obj.item()
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, dict):
        return {str(_json_safe(k)): _json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_json_safe(v) for v in obj]
    if isinstance(obj, (bytes, bytearray)):
        try:
            return obj.decode('utf-8')
        except UnicodeDecodeError:
            return str(obj)
    if hasattr(obj, 'tolist'):
        try:
            return _json_safe(obj.tolist())
        except Exception:
            pass
    if hasattr(obj, 'item'):
        try:
            return _json_safe(obj.item())
        except Exception:
            pass
    if hasattr(obj, 'shape') and hasattr(obj, 'dtype'):
        try:
            return _json_safe(np.asarray(obj).tolist())
        except Exception:
            pass
    return str(obj)


def _stable_json_dumps(obj):
    return json.dumps(
        _json_safe(obj),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )


def _config_sha256(obj):
    payload = _stable_json_dumps(obj).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _safe_config_snapshot(obj):
    return _json_safe(deepcopy(obj))


def _materialized_config_snapshot(cfg, training_config):
    full_cfg = deepcopy(cfg)
    merged_training = deepcopy(cfg.get('training', {}))
    if training_config:
        merged_training.update(deepcopy(training_config))
    full_cfg['training'] = merged_training
    return _json_safe(full_cfg)


def _materialize_mesh_config(cfg):
    """Persist an auto-resolved global mesh before checkpoint snapshots."""
    training_cfg = cfg.get('training')
    if not isinstance(training_cfg, dict):
        raise ValueError("config.training must be a mapping")
    try:
        mesh_model = int(training_cfg.get('mesh_model', 1))
        mesh_data = int(training_cfg.get('mesh_data', 0))
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "training.mesh_model and training.mesh_data must be integers") from exc
    if mesh_model <= 0 or mesh_data < 0:
        raise ValueError(
            "training mesh dimensions require mesh_model > 0 and mesh_data >= 0")
    total_devices = int(jax.device_count())
    if mesh_data == 0:
        if total_devices % mesh_model != 0:
            raise ValueError(
                f"Auto mesh_data cannot divide {total_devices} devices by "
                f"mesh_model={mesh_model}")
        mesh_data = total_devices // mesh_model
    if mesh_data * mesh_model != total_devices:
        raise ValueError(
            f"mesh_data({mesh_data}) * mesh_model({mesh_model}) = "
            f"{mesh_data * mesh_model} != {total_devices} devices")
    training_cfg['mesh_model'] = mesh_model
    training_cfg['mesh_data'] = mesh_data
    return mesh_data, mesh_model


