def _missing_config_paths(cfg, paths):
    missing = []
    for path in paths:
        cur = cfg
        for key in path:
            if (not isinstance(cur, dict)
                    or key not in cur
                    or cur[key] is None):
                missing.append('.'.join(path))
                break
            cur = cur[key]
    return missing


def _v4168_opspace_paged_runtime_resume_required_fields(pools_cfg):
    if not isinstance(pools_cfg, dict):
        return ()
    required = []
    for pool_name in V4168_OPSPACE_POOL_NAMES:
        pool_cfg = pools_cfg.get(pool_name, {})
        if not isinstance(pool_cfg, dict):
            continue
        execution_backend = str(pool_cfg.get(
            'execution_backend', '')).strip().lower()
        if execution_backend in ('paged_region_pool',
                                 'paged_region_pool_region_outer'):
            required.append(
                ('training', 'operation_space', 'pools', pool_name,
                 'page_size'))
    return tuple(required)


def _require_resume_full_config(full_config):
    if full_config is None or full_config == {}:
        raise RuntimeError(
            "Resume checkpoint is missing full_config. Automatic config "
            "fallback is disabled. Restart from scratch or use a separate "
            "explicit legacy/eval-only loader."
        )
    if not isinstance(full_config, dict):
        raise RuntimeError(
            "Resume checkpoint full_config is invalid. Expected a config "
            "dict; restart from scratch."
        )

    missing_top = [
        key for key in ('model', 'training') if key not in full_config
    ]
    if missing_top:
        raise RuntimeError(
            "Resume checkpoint full_config is incomplete: missing "
            + "/".join(missing_top)
            + ". This checkpoint cannot be resumed deterministically."
        )
    if not isinstance(full_config['model'], dict):
        raise RuntimeError(
            "Resume checkpoint full_config.model is invalid. Cannot resume "
            "deterministically."
        )
    if not isinstance(full_config['training'], dict):
        raise RuntimeError(
            "Resume checkpoint full_config.training is invalid. Cannot resume "
            "deterministically."
        )


def _validate_v4170_resume_compatibility(
        requested_model_cfg, checkpoint_model_cfg):
    requested_model_version = str(
        requested_model_cfg.get('model_version', ''))
    if requested_model_version != V4170_MODEL_VERSION:
        return
    checkpoint_model_version = str(
        checkpoint_model_cfg.get('model_version', ''))
    if checkpoint_model_version != V4170_MODEL_VERSION:
        raise RuntimeError(
            "v4170 resume requires a v4170 checkpoint; automatic "
            "migration/fallback is disabled. "
            f"requested={requested_model_version}, "
            f"checkpoint={checkpoint_model_version}")
    for field in ('d_route', 'rw_role_read_dim', 'rw_role_write_dim'):
        requested_value = requested_model_cfg.get(field)
        checkpoint_value = checkpoint_model_cfg.get(field)
        if requested_value != checkpoint_value:
            raise RuntimeError(
                "v4170 checkpoint model shape config mismatch: "
                f"model.{field} requested={requested_value}, "
                f"checkpoint={checkpoint_value}. Automatic "
                "migration/fallback is disabled.")


def _validate_v4171_resume_compatibility(
        requested_model_cfg, checkpoint_model_cfg):
    requested_version = str(requested_model_cfg.get('model_version', ''))
    if requested_version not in V417X_MODEL_VERSIONS:
        return
    checkpoint_version = str(checkpoint_model_cfg.get('model_version', ''))
    if checkpoint_version != requested_version:
        if requested_version == V4174_MODEL_VERSION:
            raise RuntimeError(
                "v4174 accepts only native v4174 checkpoints. Cross-version "
                "v4173 parameter conversion is not supported. "
                f"requested={requested_version}, checkpoint={checkpoint_version!r}")
        raise RuntimeError(
            f"{requested_version} resume requires the exact same model "
            "version checkpoint; automatic migration, random initialization, "
            "parameter conversion, and operator-key fallback are "
            "disabled. "
            f"requested={requested_version}, checkpoint={checkpoint_version}")
    if requested_version == V4173_MODEL_VERSION:
        _materialize_v4173_operation_space_config(requested_model_cfg)
        _materialize_v4173_operation_space_config(checkpoint_model_cfg)
        for field in ('n_operation_spaces', 'operation_space_top_k'):
            requested_value = requested_model_cfg[field]
            checkpoint_value = checkpoint_model_cfg[field]
            if requested_value != checkpoint_value:
                raise RuntimeError(
                    "v4173 checkpoint operation-space schema mismatch: "
                    f"model.{field} requested={requested_value}, "
                    f"checkpoint={checkpoint_value}. Automatic space "
                    "replication or migration is disabled.")
    if requested_version == V4174_MODEL_VERSION:
        requested_spaces = _resolve_v4174_operation_space_config(
            requested_model_cfg)
        checkpoint_spaces = _resolve_v4174_operation_space_config(
            checkpoint_model_cfg)
        if requested_spaces != checkpoint_spaces:
            raise RuntimeError(
                "v4174 checkpoint operation-space schema mismatch: "
                f"requested={requested_spaces}, checkpoint={checkpoint_spaces}. "
                "Automatic space replication or migration is disabled.")
    requested_den_powers = _v4171_checkpoint_den_powers(
        requested_model_cfg,
        missing_message=(
            f"{requested_version} requested full_config.model is missing "
            "admission_den_power"),
        context=f"{requested_version} requested full_config.model",
    )
    checkpoint_den_powers = _v4171_checkpoint_den_powers(
        checkpoint_model_cfg,
        missing_message=(
            f"{requested_version} checkpoint full_config.model is missing "
            "admission_den_power"),
        context=f"{requested_version} checkpoint full_config.model",
    )
    requested_den_power = requested_den_powers[0]
    checkpoint_den_power = checkpoint_den_powers[0]
    if requested_den_power != checkpoint_den_power:
        raise RuntimeError(
            f"{requested_version} checkpoint model schema mismatch: "
            "model.admission_den_power "
            f"requested={requested_den_power}, checkpoint={checkpoint_den_power}. "
            "Automatic migration/fallback is disabled.")
    for pool, requested_pool_power, checkpoint_pool_power in zip(
            ('qk', 'v', 'rst'), requested_den_powers[1:],
            checkpoint_den_powers[1:]):
        if requested_pool_power != checkpoint_pool_power:
            raise RuntimeError(
                f"{requested_version} checkpoint model schema mismatch: "
                f"model.admission_den_power_{pool} "
                f"requested={requested_pool_power}, "
                f"checkpoint={checkpoint_pool_power}. Automatic "
                "resume-time denominator changes are disabled; use "
                "params-only initialization to change pool powers.")
    requested_composition_mode = _validate_v4171_srw_composition_mode(
        requested_model_cfg.get(
            'srw_composition_mode', DEFAULT_SRW_COMPOSITION_MODE),
        context=f"{requested_version} requested full_config.model")
    checkpoint_composition_mode = _validate_v4171_srw_composition_mode(
        checkpoint_model_cfg.get(
            'srw_composition_mode', DEFAULT_SRW_COMPOSITION_MODE),
        context=f"{requested_version} checkpoint full_config.model")
    if requested_composition_mode != checkpoint_composition_mode:
        raise RuntimeError(
            f"{requested_version} checkpoint model schema mismatch: "
            "model.srw_composition_mode "
            f"requested={requested_composition_mode!r}, "
            f"checkpoint={checkpoint_composition_mode!r}. Automatic "
            "resume-time composition changes are disabled; use params-only "
            "initialization to change composition mode.")
    requested_heat_kernel_beta = _v4171_checkpoint_heat_kernel_beta(
        requested_model_cfg,
        context=f"{requested_version} requested full_config.model")
    checkpoint_heat_kernel_beta = _v4171_checkpoint_heat_kernel_beta(
        checkpoint_model_cfg,
        context=f"{requested_version} checkpoint full_config.model")
    if requested_heat_kernel_beta != checkpoint_heat_kernel_beta:
        raise RuntimeError(
            f"{requested_version} checkpoint model schema mismatch: "
            "model.heat_kernel_beta "
            f"requested={requested_heat_kernel_beta}, "
            f"checkpoint={checkpoint_heat_kernel_beta}. Automatic "
            "resume-time heat profile changes are disabled; use params-only "
            "initialization to change heat_kernel_beta.")
    required = ('d_route', 'operator_key_mode', 'operator_query_mode')
    expected_key_mode = (
        OPERATOR_KEY_MODE_LEARNED
        if requested_version == V4171_MODEL_VERSION
        else OPERATOR_KEY_MODE_GENERALIZED_BILINEAR)
    for field in required:
        requested = requested_model_cfg.get(field)
        if field == 'operator_key_mode' and requested is None:
            requested = expected_key_mode
        elif field == 'operator_query_mode' and requested is None:
            requested = 'direct_state_projection'
        checkpoint = checkpoint_model_cfg.get(field)
        if requested != checkpoint:
            raise RuntimeError(
                f"{requested_version} checkpoint model schema mismatch: "
                f"model.{field} requested={requested}, checkpoint={checkpoint}. "
                "Automatic migration/fallback is disabled.")


def _v4171_checkpoint_den_power(model_cfg, *, missing_message, context):
    if not isinstance(model_cfg, dict) or 'admission_den_power' not in model_cfg:
        raise RuntimeError(missing_message)
    try:
        return _validate_v4171_admission_den_power(
            model_cfg['admission_den_power'], context=context)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(str(exc)) from exc


def _v4171_checkpoint_den_powers(model_cfg, *, missing_message, context):
    legacy = _v4171_checkpoint_den_power(
        model_cfg, missing_message=missing_message, context=context)
    try:
        return _resolve_v417x_admission_den_powers(
            legacy,
            model_cfg.get('admission_den_power_qk'),
            model_cfg.get('admission_den_power_v'),
            model_cfg.get('admission_den_power_rst'),
            context=context)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(str(exc)) from exc


def _v4171_checkpoint_heat_kernel_beta(model_cfg, *, context):
    value = (
        model_cfg.get('heat_kernel_beta', DEFAULT_HEAT_KERNEL_BETA)
        if isinstance(model_cfg, dict)
        else DEFAULT_HEAT_KERNEL_BETA)
    try:
        return _validate_v4171_heat_kernel_beta(value, context=context)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(str(exc)) from exc


def _v4171_static_runtime_den_power(model, value, *, context,
                                    sharded_fns=None):
    (model_value, model_qk_power, model_v_power, model_rst_power) = (
        _resolve_v417x_admission_den_powers(
            getattr(model, 'admission_den_power', None),
            getattr(model, 'admission_den_power_qk', None),
            getattr(model, 'admission_den_power_v', None),
            getattr(model, 'admission_den_power_rst', None),
            context="v4171 model constructor"))
    model_mode, model_value, model_beta = _validate_v4171_composition_settings(
        getattr(
            model, 'srw_composition_mode', DEFAULT_SRW_COMPOSITION_MODE),
        getattr(model, 'admission_den_power', None),
        getattr(model, 'heat_kernel_beta', DEFAULT_HEAT_KERNEL_BETA),
        context="v4171 model constructor")
    _, runtime_value, _ = _validate_v4171_composition_settings(
        model_mode, value, model_beta, context=context)
    if runtime_value != model_value:
        raise ValueError(
            f"{context} admission_den_power={runtime_value} does not match "
            f"v4171 model constructor admission_den_power={model_value}")
    model_version = str(getattr(model, '__version__', ''))
    sharded_validator = (
        _validate_v4174_sharded_fns if model_version == V4174_MODEL_VERSION
        else (_validate_v4173_sharded_fns
              if model_version == V4173_MODEL_VERSION
              else _validate_v4171_sharded_fns))
    sharded_validator(
        sharded_fns, model_value, model_mode, model_beta,
        expected_power_qk=model_qk_power,
        expected_power_v=model_v_power,
        expected_power_rst=model_rst_power)
    return runtime_value


def _v4171_static_runtime_composition_mode(
        model, value=None, *, context, sharded_fns=None):
    (model_power, model_qk_power, model_v_power, model_rst_power) = (
        _resolve_v417x_admission_den_powers(
            getattr(model, 'admission_den_power', None),
            getattr(model, 'admission_den_power_qk', None),
            getattr(model, 'admission_den_power_v', None),
            getattr(model, 'admission_den_power_rst', None),
            context="v4171 model constructor"))
    model_mode, model_power, model_beta = _validate_v4171_composition_settings(
        getattr(
            model, 'srw_composition_mode', DEFAULT_SRW_COMPOSITION_MODE),
        getattr(model, 'admission_den_power', None),
        getattr(model, 'heat_kernel_beta', DEFAULT_HEAT_KERNEL_BETA),
        context="v4171 model constructor")
    runtime_mode = _validate_v4171_srw_composition_mode(
        model_mode if value is None else value, context=context)
    if runtime_mode != model_mode:
        raise ValueError(
            f"{context} srw_composition_mode={runtime_mode!r} does not match "
            "v4171 model constructor "
            f"srw_composition_mode={model_mode!r}")
    model_version = str(getattr(model, '__version__', ''))
    sharded_validator = (
        _validate_v4174_sharded_fns if model_version == V4174_MODEL_VERSION
        else (_validate_v4173_sharded_fns
              if model_version == V4173_MODEL_VERSION
              else _validate_v4171_sharded_fns))
    sharded_validator(
        sharded_fns, model_power, model_mode, model_beta,
        expected_power_qk=model_qk_power,
        expected_power_v=model_v_power,
        expected_power_rst=model_rst_power)
    return runtime_mode


def _v4171_static_runtime_heat_kernel_beta(
        model, value=None, *, context, sharded_fns=None):
    (model_power, model_qk_power, model_v_power, model_rst_power) = (
        _resolve_v417x_admission_den_powers(
            getattr(model, 'admission_den_power', None),
            getattr(model, 'admission_den_power_qk', None),
            getattr(model, 'admission_den_power_v', None),
            getattr(model, 'admission_den_power_rst', None),
            context="v4171 model constructor"))
    model_mode, model_power, model_beta = _validate_v4171_composition_settings(
        getattr(
            model, 'srw_composition_mode', DEFAULT_SRW_COMPOSITION_MODE),
        getattr(model, 'admission_den_power', None),
        getattr(model, 'heat_kernel_beta', DEFAULT_HEAT_KERNEL_BETA),
        context="v4171 model constructor")
    runtime_beta = _validate_v4171_heat_kernel_beta(
        model_beta if value is None else value, context=context)
    if runtime_beta != model_beta:
        raise ValueError(
            f"{context} heat_kernel_beta={runtime_beta} does not match "
            f"v4171 model constructor heat_kernel_beta={model_beta}")
    model_version = str(getattr(model, '__version__', ''))
    sharded_validator = (
        _validate_v4174_sharded_fns if model_version == V4174_MODEL_VERSION
        else (_validate_v4173_sharded_fns
              if model_version == V4173_MODEL_VERSION
              else _validate_v4171_sharded_fns))
    sharded_validator(
        sharded_fns, model_power, model_mode, model_beta,
        expected_power_qk=model_qk_power,
        expected_power_v=model_v_power,
        expected_power_rst=model_rst_power)
    return runtime_beta


def _require_resume_materialized_fields(full_config):
    model_version_missing = _missing_config_paths(
        full_config, (('model', 'model_version'),))
    if model_version_missing:
        raise RuntimeError(
            "Resume checkpoint full_config is missing required materialized "
            "fields. Automatic config fallback is disabled. Missing keys: "
            + ", ".join(model_version_missing)
        )
    model_version = full_config['model']['model_version']
    if str(model_version) == V4173_MODEL_VERSION:
        _materialize_v4173_operation_space_config(full_config['model'])
    elif str(model_version) == V4174_MODEL_VERSION:
        model_cfg = full_config['model']
        if 'n_operation_spaces' not in model_cfg:
            raise RuntimeError(
                "v4174 checkpoint metadata is missing model.n_operation_spaces")
        if 'operation_space_top_k' not in model_cfg:
            raise RuntimeError(
                "v4174 checkpoint metadata is missing model.operation_space_top_k")
        _materialize_v4174_operation_space_config(model_cfg)
    if not _is_active_srw_version(model_version):
        return
    if _is_v417x_version(model_version):
        _v4171_checkpoint_den_power(
            full_config.get('model'),
            missing_message=(
                f"{model_version} checkpoint full_config.model is missing "
                "admission_den_power"),
            context="v4171 checkpoint full_config.model",
        )
    training_cfg = (
        full_config.get('training', {})
        if isinstance(full_config.get('training', {}), dict) else {})
    opspace_cfg = (
        training_cfg.get('operation_space', {})
        if isinstance(training_cfg.get('operation_space', {}), dict) else {})
    if (str(model_version) == V4168_MODEL_VERSION
            and bool(opspace_cfg.get('enabled', False))):
        required_fields = list(V4168_OPSPACE_RESUME_REQUIRED_FIELDS)
        pools_cfg = (
            opspace_cfg.get('pools', {})
            if isinstance(opspace_cfg.get('pools', {}), dict) else {})
        rst_cfg = (
            pools_cfg.get('rst', {})
            if isinstance(pools_cfg.get('rst', {}), dict) else {})
        rst_execution_backend = str(rst_cfg.get(
            'execution_backend', '')).strip().lower()
        if rst_execution_backend == 'sparse_region_block':
            required_fields.extend(
                V4168_OPSPACE_SPARSE_RUNTIME_RESUME_REQUIRED_FIELDS)
        required_fields.extend(
            _v4168_opspace_paged_runtime_resume_required_fields(pools_cfg))
        if 'operation_space_load_smoothing' in training_cfg:
            required_fields.extend(
                V4168_OPSPACE_LOAD_SMOOTHING_RESUME_REQUIRED_FIELDS)
        repack_cfg = (
            opspace_cfg.get('repack', {})
            if isinstance(opspace_cfg.get('repack', {}), dict) else {})
        if bool(repack_cfg.get('enabled', False)):
            required_fields.extend(V4168_OPSPACE_REPACK_RESUME_REQUIRED_FIELDS)
        missing = _missing_config_paths(full_config, tuple(required_fields))
        if missing:
            raise RuntimeError(
                "Resume checkpoint full_config is missing required "
                "materialized v4168 operation-space fields. Automatic "
                "config fallback is disabled. Missing keys: "
                + ", ".join(missing)
            )
        return

    if str(model_version) in V4169_LINEAR_DIRECT_TAU_MODEL_VERSIONS:
        required_fields = (
            (V4174_RESUME_REQUIRED_FIELDS
             if str(model_version) == V4174_MODEL_VERSION else (
                 V4173_RESUME_REQUIRED_FIELDS
                 if str(model_version) == V4173_MODEL_VERSION
                 else V4171_RESUME_REQUIRED_FIELDS))
            if _is_v417x_version(model_version)
            else (V4170_RESUME_REQUIRED_FIELDS
                  if str(model_version) == V4170_MODEL_VERSION
                  else V4169_RESUME_REQUIRED_FIELDS))
        missing = _missing_config_paths(full_config, required_fields)
        if missing:
            raise RuntimeError(
                "Resume checkpoint full_config is missing required "
                f"materialized {model_version} fields. Automatic config fallback is "
                "disabled. Missing keys: " + ", ".join(missing)
            )
        forbidden_training_keys = (
            'selection_calibration',
            'selection_calibration_applied',
            'soft_gate_boundary_power_start',
            'soft_gate_boundary_power_final',
            'admission_den_power',
            'admission_den_grad_scale',
            'tau_grad_clip',
            'orthogonality_weight',
            'diversity_weight',
            'load_balance_weight',
            'tau_reg_weight',
            'dead_penalty_weight',
            'dead_penalty_qk_weight',
            'dead_penalty_v_weight',
            'dead_penalty_rst_weight',
            'dead_penalty_weighted_clip',
            'dead_exposure_target',
            'inactive_aux_enabled',
            'inactive_aux_start_frac',
            'inactive_aux_full_frac',
            'inactive_aux_schedule',
        )
        present = [
            key for key in forbidden_training_keys
            if key in training_cfg and training_cfg[key] is not None
        ]
        if (str(model_version) == V4169_MODEL_VERSION
                and 'tau_lr_mult' in training_cfg):
            present.append('tau_lr_mult')
        present.extend(
            key for key in training_cfg
            if key.startswith('cb1a_') or key.startswith('inactive_aux_')
        )
        present = sorted(set(present))
        if present:
            raise RuntimeError(
                f"Resume checkpoint full_config contains {model_version}-forbidden "
                "training fields: " + ", ".join(present)
            )
        return

    missing = _missing_config_paths(
        full_config, ACTIVE_SRW_RESUME_REQUIRED_FIELDS)
    if missing:
        raise RuntimeError(
            "Resume checkpoint full_config is missing required materialized "
            "active SRW fields. Automatic config fallback is disabled. "
            "Missing keys: " + ", ".join(missing)
        )


def _write_json_file(path, obj):
    with _open_file(path, 'w') as f:
        f.write(json.dumps(_json_safe(obj), indent=2, default=str))


def _read_json_file(path):
    with _open_file(path, 'r') as f:
        return json.loads(f.read())


